<?php $title='Product details'; require 'includes/header.php'; $id=(int)($_GET['id']??0);$p=null;if($pdo){$q=$pdo->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');$q->execute([$id]);$p=$q->fetch();}if(!$p){echo '<div class="alert alert-warning">Product not found.</div>';require 'includes/footer.php';exit;} ?>
<div class="row g-5"><div class="col-md-6"><div class="img-wrap rounded-4"><img class="w-100" style="height:430px;object-fit:cover" src="<?=url(e($p['image']))?>" alt="<?=e($p['name'])?>"></div></div><div class="col-md-6"><p class="eyebrow"><?=e($p['category_name'])?></p><h1 class="section-title"><?=e($p['name'])?></h1><div class="rating fs-6 mb-3"><i class="fa-solid fa-star"></i> <?=e($p['rating'])?> / 5</div><h2 class="price"><?=money($p['discount_price']?:$p['price'])?> <?php if($p['discount_price']):?><span class="old-price fs-6"><?=money($p['price'])?></span><?php endif;?></h2><p class="text-muted my-4"><?=e($p['description'])?></p><p><span class="badge bg-success">In stock: <?=e($p['stock'])?></span></p><form action="<?=url('cart.php')?>" method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input name="quantity" type="number" class="form-control" value="1" min="1" max="<?=$p['stock']?>" style="max-width:90px"><button name="add" class="btn btn-primary rounded-pill px-4">Add to cart</button><button name="buy" class="btn btn-outline-primary rounded-pill px-4">Buy now</button></form></div></div><?php require 'includes/footer.php'; ?>
